candidate_sql:
SELECT p.council_tax_id, c.cmi_cross_ref_id
FROM parking_fines p
LEFT JOIN cmi_cross_references c ON p.council_tax_id = c.cmi_cross_ref_id;

SELECT c.customer_name
FROM customers c
WHERE EXISTS (
    SELECT 1 FROM customer_orders o1
    WHERE o1.customer_id = c.customer_id AND o1.order_details LIKE '%Latte%'
)
AND EXISTS (
    SELECT 1 FROM customer_orders o2
    WHERE o2.customer_id = c.customer_id AND o2.order_details LIKE '%Americano%'
);
